// Zach 2.0 — fully built Sessions 5–12.
// This layer is intentionally isolated from the original Challenge Lab.

window.ZACH_SESSIONS = window.ZACH_SESSIONS || {};

const adv = {
  header(kicker,title,desc,chip='MISSION'){return stageHeader(kicker,title,desc,chip);},
  next(label='NEXT →'){return `<div class="action-row end"><button class="primary-btn" data-adv-next>${label}</button></div>`;},
  choice(id,emoji,title,text){return `<button class="choice-card" data-choice="${id}"><span class="big-emoji">${emoji}</span><strong>${title}</strong><p>${text}</p></button>`;},
  bindNext(){document.querySelectorAll('[data-adv-next]').forEach(b=>b.onclick=()=>window.zachAdvanceSessionStep());},
  requireText(sel,msg='Put your thinking into words first.'){const el=$(sel); if(!el||!el.value.trim()){toast(msg);return false;} return true;},
  note(key,val){state.notes=state.notes||{};state.notes[`s${state.programSession||1}-${key}`]=val;save();},
  complete(tag,pts=5){complete(`s${state.programSession}-${tag}`,pts);},
  finish(title,body){stage.innerHTML=adv.header('SESSION COMPLETE',title,body,'DEBRIEF')+`<div class="challenge-panel"><div class="response-box success-box"><b>Mission data saved.</b> The important part is what your brain did when the work became uncertain.</div><div class="report-grid"><div class="report-card"><h4>Hardest moment</h4><textarea id="advHard" class="notice-input"></textarea></div><div class="report-card"><h4>What worked</h4><textarea id="advWorked" class="notice-input"></textarea></div><div class="report-card"><h4>Next time</h4><textarea id="advNextTime" class="notice-input"></textarea></div></div><div class="action-row"><button id="advSaveDebrief" class="primary-btn">SAVE DEBRIEF</button></div><div id="advDebriefFeed"></div></div>`;$('#advSaveDebrief').onclick=()=>{adv.note('debrief',{hard:$('#advHard').value,worked:$('#advWorked').value,next:$('#advNextTime').value});$('#advDebriefFeed').innerHTML='<div class="response-box blue-box"><b>Good scientist move:</b> You noticed not only what happened, but how you handled it.</div>';confetti();};}
};

// ---------- SESSION 5: CURVEBALL MISSION ----------
window.ZACH_SESSIONS[5]={
 title:'Curveball Mission: Change the Plan',
 ef:'Flexibility • Planning • Regulation • Persistence',
 stages:[
 function(){
   stage.innerHTML=adv.header('SESSION 5 • COLD OPEN','Expedition Supply Drop','Build a reasonable plan with the facts you have. The mission will not stay exactly the same.','PLAN MODE')+`<div class="challenge-panel"><div class="mission-card"><span>🧭</span><div><small>YOUR ROLE</small><strong>Expedition Commander</strong><p>Deliver a science kit, water, and emergency radio to Base Camp Echo before sunset.</p></div></div><div class="constraint-strip"><span>🎒 Carry 3 items</span><span>⏱️ 18 minutes</span><span>🔋 8 power</span></div><p class="instruction">Choose your first route.</p><div class="choice-grid">${adv.choice('river','🌊','River Route','Shortest. Costs 3 power.')}${adv.choice('ridge','⛰️','Ridge Route','Longer. Costs 2 power.')}${adv.choice('forest','🌲','Forest Route','Slowest. Costs 1 power.')}${adv.choice('ask','📋','Inspect first','Review the mission before committing.')}</div><div id="s5feed"></div></div>`;
   document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{adv.note('firstRoute',b.dataset.choice);$('#s5feed').innerHTML=`<div class="response-box blue-box">Plan recorded. A plan is a starting idea, not a promise that nothing will change.</div>${adv.next('BEGIN EXPEDITION →')}`;adv.bindNext();});
 },
 function(){
   stage.innerHTML=adv.header('CURVEBALL 1','The River Changed','Identify what changed. Do not throw away parts of the plan that still work.','KEEP / CHANGE / TRY')+`<div class="challenge-panel"><div class="incoming-alert"><div class="alert-pulse">⚠️</div><div><small>FIELD UPDATE</small><strong>Heavy rain raised the river. River Route now costs 7 power instead of 3.</strong></div></div><div class="plan-update-grid"><div><small>STILL TRUE</small><strong>🎯 Same destination<br>🎒 Same cargo<br>⏱️ 18 minutes<br>🔋 8 power</strong></div><div><small>CHANGED</small><strong>🌊 River cost: 3 → 7</strong></div></div><p class="instruction">What is the strongest move?</p><div class="choice-grid">${adv.choice('keep','➡️','Keep everything','A plan is a plan.')}${adv.choice('adjust','🧭','Change only the route','Keep the goal and cargo; reconsider the path.')}${adv.choice('restart','🔄','Restart everything','Choose new cargo and a new goal too.')}${adv.choice('quit','🛑','Stop the mission','The plan changed.')}</div><div id="s5curve1"></div></div>`;
   document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='adjust'){adv.note('curve1','adjust');$('#s5curve1').innerHTML=`<div class="response-box success-box"><b>Exactly.</b> The route changed. The mission did not. Strong flexibility means changing the part that needs changing.</div>${adv.next('KEEP MOVING →')}`;adv.complete('curve1',6);adv.bindNext();}else{$('#s5curve1').innerHTML='<div class="response-box">Check the facts: what actually changed, and what is still completely usable?</div>';}});
 },
 function(){
   stage.innerHTML=adv.header('CURVEBALL 2','Cargo Trouble','A broken tool forces a resource decision.','DECISION MODE')+`<div class="challenge-panel"><div class="mission-card"><span>📦</span><div><small>NEW PROBLEM</small><strong>The science-kit case cracked.</strong><p>You can carry only two of its three modules: microscope, sample jars, weather sensor.</p></div></div><p class="instruction">Base Camp says its priority is collecting storm evidence before the weather clears. What do you keep?</p><div class="choice-grid">${adv.choice('microscope','🔬','Microscope + jars','Best for examining samples later.')}${adv.choice('weather','🌦️','Weather sensor + jars','Collects storm measurements and physical samples.')}${adv.choice('random','🎲','Pick any two','All tools are equal.')}${adv.choice('all','🎒','Carry all three anyway','Ignore the new limit.')}</div><div id="s5cargo"></div></div>`;
   document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='weather'){adv.note('cargo','weather+jars');$('#s5cargo').innerHTML=`<div class="response-box success-box"><b>Priority matched.</b> You used the new goal information instead of treating every resource as equally important.</div>${adv.next('READ THE NEXT CLUE →')}`;adv.complete('cargo',6);adv.bindNext();}else{$('#s5cargo').innerHTML='<div class="response-box">Which choice best matches the words <b>storm evidence before the weather clears</b>?</div>';}});
 },
 function(){
   stage.innerHTML=adv.header('CURVEBALL 3 • READ','The Clue Changes the Map','New evidence can change what an old clue means.','READ + REPLAN')+`<div class="reading-card">The ranger note says: “Avoid the ridge if the wind flag points east. The forest is slower, but the trees block most crosswind.”</div><div class="challenge-panel"><div class="wind-flag">🚩 <b>Current flag: EAST</b></div><p class="instruction">You had selected the ridge after the river became unsafe. What now?</p><textarea id="s5explain" class="notice-input" placeholder="What changed? What stays? What route would you use now, and why?"></textarea><div class="action-row"><button id="s5explainBtn" class="primary-btn">COMMIT NEW PLAN</button></div><div id="s5readFeed"></div></div>`;
   $('#s5explainBtn').onclick=()=>{if(!adv.requireText('#s5explain'))return;adv.note('readReplan',$('#s5explain').value);$('#s5readFeed').innerHTML=`<div class="response-box success-box">The strongest answer uses the <b>forest</b> because the east-wind warning changes the ridge condition. More important: you explained the evidence behind your change.</div>${adv.next('BOSS MISSION →')}`;adv.complete('read-replan',6);adv.bindNext();};
 },
 function(){
   let phase=0;
   stage.innerHTML=adv.header('SESSION 5 • BOSS','Storm Rescue','Three updates. Your job is to preserve what works and change only what the facts require.','BOSS MODE')+`<div class="challenge-panel"><div class="boss-map"><span>🏠 BASE</span><b>→</b><span>🌲 FOREST</span><b>→</b><span>🪨 PASS</span><b>→</b><span>🏕️ ECHO</span></div><div id="s5bossAlert" class="response-box blue-box"><b>Start:</b> 10 power, 16 minutes, medicine package loaded.</div><div id="s5bossChoices" class="choice-grid"></div><div id="s5bossFeed"></div></div>`;
   const rounds=[
     {alert:'A fallen tree blocks Forest. Detour costs +2 power.',opts:[['detour','🧭','Take detour','Goal and cargo remain valid.'],['restart','🔄','Restart mission','Throw out everything.']],good:'detour'},
     {alert:'Echo reports medicine is still needed, but the radio is no longer needed.',opts:[['drop','📻','Drop radio','Reduce load; keep medicine.'],['dropmed','💊','Drop medicine','Change the main goal.']],good:'drop'},
     {alert:'You have 5 power left. Pass now costs 4. It is still open.',opts:[['continue','⚡','Continue','5 − 4 leaves 1.'],['switch','🔄','Switch routes again','Change because something changed.']],good:'continue'}
   ];
   function renderRound(){const r=rounds[phase];$('#s5bossAlert').innerHTML=`<b>UPDATE ${phase+1}:</b> ${r.alert}`;$('#s5bossChoices').innerHTML=r.opts.map(o=>adv.choice(o[0],o[1],o[2],o[3])).join('');document.querySelectorAll('#s5bossChoices [data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice===r.good){phase++;if(phase===rounds.length){$('#s5bossChoices').innerHTML='';$('#s5bossFeed').innerHTML=`<div class="response-box success-box"><b>RESCUE COMPLETE.</b> You changed when the facts required it—and stayed with the plan when it still worked.</div>${adv.next('DEBRIEF →')}`;adv.complete('boss',10);adv.bindNext();}else{beep(650,.08);renderRound();}}else{$('#s5bossFeed').innerHTML='<div class="response-box">Ask: what changed? Does that change the goal, or only one part of the plan?</div>';}});}
   renderRound();
 },
 function(){adv.finish('Curveball Mission Complete','A changed plan is not a ruined plan. Strong planners keep what works, change what must change, and then try again.');}
 ]
};

// ---------- SESSION 6: HINT ECONOMY ----------
window.ZACH_SESSIONS[6]={title:'Hint Economy: When Should I Ask for Help?',ef:'Help-Seeking • Persistence • Self-Monitoring • Planning',stages:[
 function(){stage.innerHTML=adv.header('SESSION 6 • CALIBRATION','Thinking or Stuck?','Before you ask for help, know what kind of moment you are in.','STUCK METER')+`<div class="challenge-panel"><div class="stuck-meter"><button data-level="green">🟢<b>Thinking</b><small>I am still generating ideas.</small></button><button data-level="yellow">🟡<b>Trying</b><small>I tested at least one idea.</small></button><button data-level="orange">🟠<b>Stuck</b><small>I tried useful ideas and have no next move.</small></button><button data-level="red">🔴<b>Frustrated</b><small>My brain/body needs a reset.</small></button></div><p class="instruction">Scenario: You have read a puzzle once and do not see the answer yet. Where are you?</p><div id="s6meterFeed"></div></div>`;document.querySelectorAll('[data-level]').forEach(b=>b.onclick=()=>{if(b.dataset.level==='green'){adv.note('meter','green');$('#s6meterFeed').innerHTML=`<div class="response-box success-box">Right. Not knowing immediately is often just <b>thinking time</b>.</div>${adv.next('OPEN HINT BANK →')}`;adv.bindNext();}else $('#s6meterFeed').innerHTML='<div class="response-box">You have not tried anything yet. Is that really stuck—or are you still thinking?</div>';});},
 function(){let used=0;stage.innerHTML=adv.header('HINT BANK','The Locked Number','Hints are tools. Use the smallest amount of help that gets your brain moving again.','3 HINT LEVELS')+`<div class="challenge-panel"><div class="mystery-lock">🔐 <span>2 • 6 • 12 • 20 • ?</span></div><p class="instruction">Find the next number. Try first. If you use help, choose how much.</p><textarea id="s6try" class="notice-input" placeholder="What pattern do you notice or what have you tried?"></textarea><div class="hint-bank"><button data-help="1">💡 NUDGE<small>Small clue</small></button><button data-help="2">🧭 STRATEGY<small>Suggest a method</small></button><button data-help="3">🛟 DIRECT HELP<small>Reveal most of the missing step</small></button></div><div id="s6hintFeed"></div><div class="action-row"><button id="s6solve" class="primary-btn">CHECK ANSWER</button></div></div>`;document.querySelectorAll('[data-help]').forEach(b=>b.onclick=()=>{if(!adv.requireText('#s6try','Tell what you tried before spending a hint.'))return;used=Math.max(used,Number(b.dataset.help));const texts={1:'Look at how much each number increases by.',2:'Write the jumps: +4, +6, +8. What might the next jump be?',3:'The jumps grow by 2 each time. The next jump is +10.'};$('#s6hintFeed').innerHTML=`<div class="response-box blue-box"><b>Help level ${b.dataset.help}:</b> ${texts[b.dataset.help]}</div>`;});$('#s6solve').onclick=()=>{const t=$('#s6try').value;if(/30/.test(t)){adv.note('numberHint',used);$('#s6hintFeed').innerHTML=`<div class="response-box success-box"><b>30.</b> Your help choice mattered too. The goal is not “never use hints.” It is “use enough help to restart your own thinking.”</div>${adv.next('HELP OR KEEP GOING? →')}`;adv.complete('number',6);adv.bindNext();}else toast('Add your answer and reasoning to the box.');};},
 function(){let score=0,round=0;const qs=[{s:'You have tried two sensible routes through a maze and both hit walls. You can name exactly where you are stuck.',a:'help'},{s:'You just opened a new reading and one word is unfamiliar, but the rest of the sentence gives clues.',a:'try'},{s:'The teacher says “put it over there,” but there are three possible places and no other clue.',a:'help'},{s:'Your first math answer was wrong and you have not checked your work yet.',a:'try'}];stage.innerHTML=adv.header('DECISION LAB','Help or Keep Going?','Sometimes asking is smart. Sometimes you still have a useful next move.','METACOGNITION')+`<div class="challenge-panel"><div id="s6scenario" class="scenario-card"></div><div class="choice-grid"><button class="choice-card" id="s6tryAgain"><span class="big-emoji">🚀</span><strong>TRY ANOTHER MOVE</strong></button><button class="choice-card" id="s6askHelp"><span class="big-emoji">🙋</span><strong>ASK SPECIFICALLY</strong></button></div><div id="s6decisionFeed"></div></div>`;function show(){if(round>=qs.length){$('#s6scenario').innerHTML=`<b>Decision round complete: ${score}/${qs.length}</b>`;$('#s6decisionFeed').innerHTML=`<div class="response-box success-box">Good help-seeking is a decision skill, not a weakness.</div>${adv.next('CLASSROOM HELP →')}`;adv.complete('decision',7);adv.bindNext();return;}$('#s6scenario').textContent=qs[round].s;$('#s6decisionFeed').innerHTML='';}function choose(a){if(a===qs[round].a){score++;round++;show();}else $('#s6decisionFeed').innerHTML='<div class="response-box">Check whether you still have a useful strategy available—or whether information is truly missing.</div>';};$('#s6tryAgain').onclick=()=>choose('try');$('#s6askHelp').onclick=()=>choose('help');show();},
 function(){stage.innerHTML=adv.header('SCHOOL TRANSFER','Make the Question Useful','“Help me” is less powerful than saying exactly what part is unclear.','CLASSROOM MODE')+`<div class="challenge-panel"><div class="reading-card">Teacher directions: “Circle the words that show action. Then sort them into two groups using the labels on the board.”</div><div class="response-box alert-box"><b>Problem:</b> The labels on the board are covered by a projector window.</div><p class="instruction">Which question gives the teacher the best information?</p><div class="choice-grid">${adv.choice('a','🙋','I don’t get it.','General request.')}${adv.choice('b','🎯','I know how to circle the action words, but I can’t see the two group labels. What are the labels?','Specific missing information.')}${adv.choice('c','🚪','Can I skip this?','Avoid the task.')}${adv.choice('d','🤷','What do I do?','Does not identify the stuck point.')}</div><div id="s6schoolFeed"></div></div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='b'){$('#s6schoolFeed').innerHTML=`<div class="response-box success-box">Exactly. You showed what you understand and named the exact missing piece.</div>${adv.next('BOSS CHALLENGE →')}`;adv.complete('school-help',6);adv.bindNext();}else $('#s6schoolFeed').innerHTML='<div class="response-box">Make the question show what you already understand and what exact information is missing.</div>';});},
 function(){let tried=false;stage.innerHTML=adv.header('SESSION 6 • BOSS','The Impossible Door','One part of this mission cannot be solved without asking. Your job is to recognize that point.','HELP-SEEKING BOSS')+`<div class="challenge-panel"><div class="mystery-door">🚪<b>VAULT 4</b><small>Enter the animal code.</small></div><div class="reading-card">Clue 1: The code is an animal with four legs.<br>Clue 2: It lives on land.<br>Clue 3: It is not a pet.</div><input id="s6animal" class="notice-input" placeholder="Try an answer or explain the problem..."><div class="action-row"><button id="s6testAnimal" class="primary-btn">TEST IDEA</button><button id="s6specificHelp" class="secondary-btn">ASK A SPECIFIC QUESTION</button></div><div id="s6bossFeed"></div></div>`;$('#s6testAnimal').onclick=()=>{tried=true;$('#s6bossFeed').innerHTML='<div class="response-box alert-box">ACCESS DENIED. Many animals fit all three clues. Testing another random animal may not teach you enough.</div>';};$('#s6specificHelp').onclick=()=>{if(!tried){$('#s6bossFeed').innerHTML='<div class="response-box">What have you tried or noticed first?</div>';return;}$('#s6bossFeed').innerHTML=`<div class="response-box success-box"><b>Correct decision.</b> The clues do not give enough information for one answer. A strong question could be: “Can you give me one clue that separates the possible animals?”</div><div class="response-box blue-box"><b>New clue:</b> It has black-and-white stripes.</div><div class="action-row"><button id="s6zebra" class="primary-btn">ENTER: ZEBRA</button></div>`;$('#s6zebra').onclick=()=>{$('#s6bossFeed').innerHTML=`<div class="response-box success-box"><b>VAULT OPEN.</b> Asking was the independent move because the task genuinely lacked enough information.</div>${adv.next('MIDPOINT CHECK →')}`;adv.complete('boss',10);adv.bindNext();};};},
 function(){adv.finish('Hint Economy Complete','Strong learners try, monitor whether they are making progress, and ask a specific question when another useful move is not available.');}
]};

// ---------- SESSION 7: PLAN IT YOURSELF ----------
window.ZACH_SESSIONS[7]={title:'Plan It Yourself',ef:'Task Initiation • Planning • Working Memory • Focus',stages:[
 function(){stage.innerHTML=adv.header('SESSION 7 • COLD OPEN','Launch Day','You get the goal and constraints. Nobody gives you the order.','YOU PLAN IT')+`<div class="challenge-panel"><div class="mission-card"><span>🚀</span><div><small>GOAL</small><strong>Launch the research rover.</strong><p>Before launch: charge battery, load map, pack camera, test wheels, send launch code.</p></div></div><div class="constraint-strip"><span>⚡ Charge before wheel test</span><span>🗺️ Map before launch code</span><span>📷 Camera can happen anytime</span></div><p class="instruction">Build your sequence before touching launch.</p><textarea id="s7plan" class="notice-input" placeholder="Write or dictate the order you would use..."></textarea><div class="action-row"><button id="s7planBtn" class="primary-btn">LOCK PLAN</button></div><div id="s7planFeed"></div></div>`;$('#s7planBtn').onclick=()=>{if(!adv.requireText('#s7plan'))return;adv.note('initialPlan',$('#s7plan').value);$('#s7planFeed').innerHTML=`<div class="response-box blue-box"><b>Plan locked.</b> Now we can test whether the order works instead of making one move at a time with no map.</div>${adv.next('EXECUTE →')}`;adv.bindNext();};},
 function(){let done=[];const tasks={charge:'Charge battery',map:'Load map',camera:'Pack camera',wheels:'Test wheels',code:'Send launch code'};stage.innerHTML=adv.header('EXECUTION','Run Your Sequence','Use your plan. If you discover an order problem, revise it.','PLAN → DO → CHECK')+`<div class="challenge-panel"><div class="task-board">${Object.entries(tasks).map(([k,v])=>`<button data-task="${k}">${v}</button>`).join('')}</div><div id="s7execFeed"></div></div>`;document.querySelectorAll('[data-task]').forEach(b=>b.onclick=()=>{const k=b.dataset.task;if(done.includes(k))return;if(k==='wheels'&&!done.includes('charge')){$('#s7execFeed').innerHTML='<div class="response-box alert-box">Wheel test failed: battery is not charged yet. Your plan just gave you information. What should move earlier?</div>';return;}if(k==='code'&&!done.includes('map')){$('#s7execFeed').innerHTML='<div class="response-box alert-box">Launch code cannot be sent until navigation map is loaded. Revise the order.</div>';return;}done.push(k);b.classList.add('task-done');b.disabled=true;if(done.length===5){$('#s7execFeed').innerHTML=`<div class="response-box success-box"><b>All pre-launch jobs complete.</b> You used a sequence and revised only if evidence required it.</div>${adv.next('ORGANIZE THE FIELD KIT →')}`;adv.complete('sequence',7);adv.bindNext();}});},
 function(){let picked=[];stage.innerHTML=adv.header('ORGANIZE','Field Kit Planner','Planning also means deciding what information and materials belong together.','ORGANIZATION')+`<div class="challenge-panel"><p class="instruction">Mission: photograph insects at a pond and record temperature. Choose exactly 5 useful items.</p><div class="inventory-grid">${[['camera','📷 Camera'],['therm','🌡️ Thermometer'],['notebook','📓 Notebook'],['net','🕸️ Bug net'],['boots','🥾 Boots'],['soccer','⚽ Soccer ball'],['pillow','🛏️ Pillow'],['spoon','🥄 Spoon']].map(x=>`<button data-item="${x[0]}">${x[1]}</button>`).join('')}</div><div id="s7inventoryCount" class="response-box blue-box">0 / 5 selected</div><div class="action-row"><button id="s7pack" class="primary-btn">PACK KIT</button></div><div id="s7packFeed"></div></div>`;document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>{const k=b.dataset.item;if(picked.includes(k)){picked=picked.filter(x=>x!==k);b.classList.remove('selected');}else if(picked.length<5){picked.push(k);b.classList.add('selected');}$('#s7inventoryCount').textContent=`${picked.length} / 5 selected`;});$('#s7pack').onclick=()=>{const useful=['camera','therm','notebook','net','boots'];if(picked.length!==5){toast('Choose exactly 5.');return;}const good=useful.every(x=>picked.includes(x));$('#s7packFeed').innerHTML=good?`<div class="response-box success-box">Everything in the kit connects to the mission. That is organization with a purpose.</div>${adv.next('MID-MISSION CHECK →')}`:'<div class="response-box">One selected item does not help photograph insects, collect/observe them, record data, or work safely at a pond. Recheck the goal.</div>';if(good){adv.complete('organize',6);adv.bindNext();}};},
 function(){stage.innerHTML=adv.header('MID-MISSION CHECK','Is the Plan Working?','A plan is useful only if you check it before the very end.','SELF-CHECK')+`<div class="challenge-panel"><div class="progress-board"><span>✅ Camera packed</span><span>✅ Thermometer packed</span><span>⚠️ Notebook battery? No battery needed.</span><span>❌ Boots still at base</span><span>⏱️ 6 minutes left</span></div><p class="instruction">What should happen next?</p><textarea id="s7check" class="notice-input" placeholder="What is already done? What needs attention now?"></textarea><div class="action-row"><button id="s7checkBtn" class="primary-btn">CHECK PLAN</button></div><div id="s7checkFeed"></div></div>`;$('#s7checkBtn').onclick=()=>{if(!adv.requireText('#s7check'))return;adv.note('midCheck',$('#s7check').value);$('#s7checkFeed').innerHTML=`<div class="response-box success-box"><b>Key idea:</b> Ignore the fake problem about a notebook battery. The real unfinished job is the boots. Good planners check against the goal, not every piece of noise.</div>${adv.next('SCHOOL TRANSFER →')}`;adv.complete('midcheck',6);adv.bindNext();};},
 function(){stage.innerHTML=adv.header('SCHOOL TRANSFER','Independent Work Block','Your teacher gives the assignment, not the sequence.','2ND GRADE SIM')+`<div class="challenge-panel"><div class="reading-card">Finish before the timer: read the animal paragraph, answer 3 questions, draw and label the habitat, check your name, turn it in.</div><p class="instruction">Before starting, make a plan that avoids forgetting the easy last steps.</p><textarea id="s7schoolPlan" class="notice-input" placeholder="My order will be..."></textarea><div class="action-row"><button id="s7schoolPlanBtn" class="primary-btn">START WORK BLOCK</button></div><div id="s7schoolPlanFeed"></div></div>`;$('#s7schoolPlanBtn').onclick=()=>{if(!adv.requireText('#s7schoolPlan'))return;adv.note('schoolPlan',$('#s7schoolPlan').value);$('#s7schoolPlanFeed').innerHTML=`<div class="response-box success-box">You created the sequence instead of waiting for one. That is the exact independence move this session is training.</div>${adv.next('PLANNING BOSS →')}`;adv.complete('school',6);adv.bindNext();};},
 function(){stage.innerHTML=adv.header('SESSION 7 • BOSS','Mars Base Setup','You get the mission. You make the sequence, organize resources, and decide when to check progress.','PLANNING BOSS')+`<div class="challenge-panel"><div class="mission-card"><span>🔴</span><div><strong>Build a safe Mars base before the dust storm.</strong><p>Requirements: power online, shelter sealed, antenna raised, 2 oxygen tanks inside, rover parked under cover. Antenna requires power. Rover cover cannot be sealed until rover is inside.</p></div></div><textarea id="s7bossPlan" class="notice-input" style="min-height:160px" placeholder="Write the complete plan before launch..."></textarea><div class="action-row"><button id="s7bossBtn" class="primary-btn">RUN MY PLAN</button></div><div id="s7bossFeed"></div></div>`;$('#s7bossBtn').onclick=()=>{if(!adv.requireText('#s7bossPlan'))return;adv.note('bossPlan',$('#s7bossPlan').value);$('#s7bossFeed').innerHTML=`<div class="response-box success-box"><b>MISSION SIMULATED.</b> Now check your plan: Is power before antenna? Is rover inside before sealing its cover? Are both oxygen tanks accounted for?</div><div class="action-row"><button id="s7bossConfirm" class="primary-btn">I CHECKED + REVISED</button></div>`;$('#s7bossConfirm').onclick=()=>{$('#s7bossFeed').innerHTML=`<div class="response-box success-box">Planning is not guessing the perfect order. It is building a workable sequence, checking constraints, and revising before the problem gets expensive.</div>${adv.next('DEBRIEF →')}`;adv.complete('boss',10);adv.bindNext();};};},
 function(){adv.finish('Plan It Yourself Complete','The goal was not to follow a plan. It was to create one, use it, and check it without waiting for an adult to supply the sequence.');}
]};

// ---------- SESSION 8: FIND IT, FIX IT, PROVE IT ----------
window.ZACH_SESSIONS[8]={title:'Find It, Fix It, Prove It',ef:'Self-Monitoring • Persistence • Reading Confidence • Focus',stages:[
 function(){stage.innerHTML=adv.header('SESSION 8 • ERROR HUNT','The Answer Is Already Wrong','Your job is not to avoid mistakes. Your job is to detect them.','DEBUG MODE')+`<div class="challenge-panel"><div class="error-card"><b>Robot route:</b> Start at A → move right 3 → up 2 → left 1.<br><b>Robot report:</b> “I ended 4 spaces right of A.”</div><p class="instruction">What should you check first?</p><div class="choice-grid">${adv.choice('steps','🔎','Replay the moves','Check the report against the actual route.')}${adv.choice('trust','✅','Trust the robot','It sounds confident.')}${adv.choice('redo','🗑️','Delete everything','Start over without checking.')}${adv.choice('guess','🎲','Guess a new answer','Change it randomly.')}</div><div id="s8hunt"></div></div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='steps'){$('#s8hunt').innerHTML=`<div class="response-box success-box">3 right, then 1 left = <b>2 spaces right</b>. You found the mismatch by checking evidence.</div>${adv.next('BROKEN DIRECTIONS →')}`;adv.complete('hunt',6);adv.bindNext();}else $('#s8hunt').innerHTML='<div class="response-box">Debuggers do not replace an answer before they know what is wrong. Check the evidence.</div>';});},
 function(){stage.innerHTML=adv.header('ERROR TYPE 2','Broken Directions','Sometimes the error is in the instructions, not in you.','CHECK THE SOURCE')+`<div class="challenge-panel"><div class="directions-list"><div class="direction">Color the triangle blue.</div><div class="direction">Do not color any shapes blue.</div><div class="direction">Circle the square.</div><div class="direction">Write your name.</div></div><p class="instruction">Find the exact conflict and repair it.</p><textarea id="s8directions" class="notice-input" placeholder="The conflict is... A possible repair is..."></textarea><div class="action-row"><button id="s8dirBtn" class="primary-btn">PROVE THE ERROR</button></div><div id="s8dirFeed"></div></div>`;$('#s8dirBtn').onclick=()=>{if(!adv.requireText('#s8directions'))return;adv.note('directionsFix',$('#s8directions').value);$('#s8dirFeed').innerHTML=`<div class="response-box success-box">The first two directions cannot both be followed. Catching that is self-monitoring, not “being confused.”</div>${adv.next('READING DETECTIVE →')}`;adv.complete('directions',6);adv.bindNext();};},
 function(){stage.innerHTML=adv.header('ERROR TYPE 3','Evidence Detective','A confident sentence can still conflict with the evidence.','READ + VERIFY')+`<div class="reading-card">Milo watched the sky darken. Wind bent the tall grass and the first drops hit the pond. He grabbed his jacket and hurried toward the cabin.</div><div class="challenge-panel"><div class="error-card"><b>Student answer:</b> “Milo hurried to the cabin because it was getting very hot and sunny.”</div><p class="instruction">Which evidence disproves the answer?</p><div class="choice-grid">${adv.choice('dark','🌧️','Dark sky + rain','These details point to a storm.')}${adv.choice('pond','💧','There is a pond','True but not relevant.')}${adv.choice('milo','👦','His name is Milo','True but not evidence.')}${adv.choice('grass','🌾','There is grass','Not enough by itself.')}</div><div id="s8read"></div></div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='dark'){$('#s8read').innerHTML=`<div class="response-box success-box"><b>Proved.</b> Darkening sky, wind, and drops contradict “hot and sunny.”</div>${adv.next('DESIGN FLAW →')}`;adv.complete('reading',6);adv.bindNext();}else $('#s8read').innerHTML='<div class="response-box">Find evidence that directly conflicts with “hot and sunny.”</div>';});},
 function(){stage.innerHTML=adv.header('ERROR TYPE 4','Hidden Design Flaw','The structure looks finished. Find the problem before testing it.','ENGINEER CHECK')+`<div class="challenge-panel"><div class="bridge-diagram"><span>🪨</span><i>━━━━━━</i><span>🪨</span><small>Support placed only at the far ends</small><b>🚚 heavy truck must stop in the middle</b></div><p class="instruction">What should an engineer inspect before sending the truck?</p><textarea id="s8bridge" class="notice-input" placeholder="The risky part is... I would fix/check it by..."></textarea><div class="action-row"><button id="s8bridgeBtn" class="primary-btn">TEST MY REPAIR</button></div><div id="s8bridgeFeed"></div></div>`;$('#s8bridgeBtn').onclick=()=>{if(!adv.requireText('#s8bridge'))return;adv.note('bridgeFix',$('#s8bridge').value);$('#s8bridgeFeed').innerHTML=`<div class="response-box success-box">A strong answer notices the unsupported middle and adds/strengthens support where the load will be highest.</div>${adv.next('PROVE IT →')}`;adv.complete('design',6);adv.bindNext();};},
 function(){stage.innerHTML=adv.header('PROOF MODE','Which Answer Can You Defend?','Do not choose the answer you like. Choose the one you can prove.','EVIDENCE')+`<div class="challenge-panel"><div class="reading-card">Three animals crossed the trail. Fox tracks were on top of rabbit tracks. Deer tracks crossed both but were partly filled with fresh snow.</div><p class="instruction">Which claim has the strongest evidence?</p><div class="choice-grid">${adv.choice('fox','🦊','Fox came after rabbit','Fox tracks lie on top of rabbit tracks.')}${adv.choice('deer','🦌','Deer definitely came last','Snow makes timing less certain.')}${adv.choice('rabbit','🐇','Rabbit came last','Its tracks are underneath fox tracks.')}${adv.choice('none','❓','No conclusion is possible','There is useful overlap evidence.')}</div><div id="s8proof"></div></div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='fox'){$('#s8proof').innerHTML=`<div class="response-box success-box">That claim is supported directly by track overlap. “Can I prove it?” is a powerful self-check.</div>${adv.next('DEBUGGING BOSS →')}`;adv.complete('proof',6);adv.bindNext();}else $('#s8proof').innerHTML='<div class="response-box">Choose the claim tied to the clearest physical evidence.</div>';});},
 function(){let found=0;stage.innerHTML=adv.header('SESSION 8 • BOSS','System Debug','Find three different error types before the system launches.','BOSS MODE')+`<div class="challenge-panel"><div class="debug-grid"><button data-bug="math"><b>Math panel</b><small>8 + 7 = 14</small></button><button data-bug="read"><b>Reading panel</b><small>Text says nocturnal; answer says active in daytime.</small></button><button data-bug="rule"><b>Rule panel</b><small>“Choose exactly 2” but 3 choices are selected.</small></button><button data-bug="ok"><b>Power panel</b><small>Battery 90% — required ≥80%.</small></button></div><div id="s8bossFeed"></div></div>`;document.querySelectorAll('[data-bug]').forEach(b=>b.onclick=()=>{if(b.dataset.bug==='ok'){$('#s8bossFeed').innerHTML='<div class="response-box">That panel meets its rule. Debuggers also need to recognize what is already correct.</div>';return;}if(b.classList.contains('bug-found'))return;b.classList.add('bug-found');found++;$('#s8bossFeed').innerHTML=`<div class="response-box blue-box">Bug ${found}/3 found. Explain what evidence proves it before choosing another.</div>`;if(found===3){$('#s8bossFeed').innerHTML=`<div class="response-box success-box"><b>SYSTEM CLEAN.</b> You checked math accuracy, evidence consistency, and rule compliance—three different kinds of self-monitoring.</div>${adv.next('DEBRIEF →')}`;adv.complete('boss',10);adv.bindNext();}});},
 function(){adv.finish('Find It, Fix It, Prove It Complete','Mistakes are information. The independence skill is noticing them, locating the cause, repairing them, and proving the repair.');}
]};

// ---------- SESSION 9: OPEN MISSION ----------
window.ZACH_SESSIONS[9]={title:'Open Mission: You Choose the Strategy',ef:'Initiation • Persistence • Flexibility • Help-Seeking • Self-Monitoring',stages:[
 function(){stage.innerHTML=adv.header('SESSION 9 • OPEN MISSION','Signal Lost','No EF lesson is announced. You choose how to attack the mission.','INDEPENDENCE TEST')+`<div class="challenge-panel"><div class="mission-card"><span>📡</span><div><small>SITUATION</small><strong>A research drone stopped transmitting from Island 7.</strong><p>You have a map fragment, 6 energy units, a repair kit, rope, scanner, and one optional hint channel. Recover its data core.</p></div></div><textarea id="s9first" class="notice-input" placeholder="What is your first move—and why?"></textarea><div class="action-row"><button id="s9firstBtn" class="primary-btn">BEGIN MISSION</button></div><div id="s9firstFeed"></div></div>`;$('#s9firstBtn').onclick=()=>{if(!adv.requireText('#s9first'))return;adv.note('firstMove',$('#s9first').value);$('#s9firstFeed').innerHTML=`<div class="response-box blue-box">Mission started. I will not tell you which EF tool this is “supposed” to use.</div>${adv.next('ENTER ISLAND →')}`;adv.bindNext();};},
 function(){let scans=0;stage.innerHTML=adv.header('OPEN MISSION','Island Evidence','Gather enough information to choose a route. Scanning costs energy.','RESOURCE DECISION')+`<div class="challenge-panel"><div class="island-map"><button data-scan="beach">🏖️ Beach<small>Cost 1</small></button><button data-scan="jungle">🌴 Jungle<small>Cost 1</small></button><button data-scan="cliff">🪨 Cliff<small>Cost 1</small></button></div><div id="s9energy" class="constraint-strip"><span>⚡ Energy: 6</span><span>🔎 Scans: 0</span></div><div id="s9evidence" class="evidence-list"></div><div class="action-row"><button id="s9commitRoute" class="primary-btn">I HAVE ENOUGH INFORMATION</button></div><div id="s9routeFeed"></div></div>`;const info={beach:'Fresh tire marks head inland.',jungle:'Broken branches form a wide path; scanner finds metal 200m north.',cliff:'Strong signal reflection but no tire marks.'};document.querySelectorAll('[data-scan]').forEach(b=>b.onclick=()=>{if(b.disabled)return;b.disabled=true;scans++;$('#s9energy').innerHTML=`<span>⚡ Energy: ${6-scans}</span><span>🔎 Scans: ${scans}</span>`;$('#s9evidence').innerHTML+=`<div class="evidence-item evidence-pass"><b>${b.textContent.trim()}</b><small>${info[b.dataset.scan]}</small></div>`;});$('#s9commitRoute').onclick=()=>{if(scans<1){toast('Use at least one piece of evidence before committing.');return;}adv.note('scans',scans);$('#s9routeFeed').innerHTML=`<div class="response-box success-box">You decided when you had enough information rather than scanning automatically forever.</div>${adv.next('CURVEBALL →')}`;adv.complete('evidence',6);adv.bindNext();};},
 function(){stage.innerHTML=adv.header('OPEN MISSION • CURVEBALL','The Map Is Wrong','One old assumption breaks. Choose your own response.','FLEXIBILITY')+`<div class="challenge-panel"><div class="incoming-alert"><div class="alert-pulse">⚠️</div><div><small>FIELD UPDATE</small><strong>The marked bridge does not exist. A fallen tree can serve as a crossing if reinforced with rope.</strong></div></div><textarea id="s9curve" class="notice-input" placeholder="What would you do now? Explain what information matters."></textarea><div class="action-row"><button id="s9curveBtn" class="primary-btn">TRY MY PLAN</button><button class="secondary-btn" id="s9openHint">OPTIONAL HINT CHANNEL</button></div><div id="s9curveFeed"></div></div>`;$('#s9openHint').onclick=()=>showModal('💡','OPTIONAL HINT','Separate the goal from the route. Is the missing bridge the goal—or just one way to get there?');$('#s9curveBtn').onclick=()=>{if(!adv.requireText('#s9curve'))return;adv.note('curve',$('#s9curve').value);$('#s9curveFeed').innerHTML=`<div class="response-box success-box">The mission can continue if your plan uses the new crossing evidence and protects enough energy/resources for the repair.</div>${adv.next('RECOVER THE CORE →')}`;adv.complete('curve',7);adv.bindNext();};},
 function(){stage.innerHTML=adv.header('OPEN MISSION','Drone Recovery','You reached the drone. Diagnose before repairing.','SELF-MONITOR')+`<div class="challenge-panel"><div class="machine-brief"><div class="machine-problem">🤖 <div><small>DRONE STATUS</small><strong>Power: ON • Wheels: ON • Camera: ON • Radio: OFF</strong></div></div></div><p class="instruction">You have one repair kit. What component deserves it?</p><div class="choice-grid">${adv.choice('radio','📡','Radio','It is the only failed system.')}${adv.choice('wheels','🛞','Wheels','They are important.')}${adv.choice('camera','📷','Camera','It has the data.')}${adv.choice('random','🎲','Random part','Repairs are experiments.')}</div><div id="s9repair"></div></div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{if(b.dataset.choice==='radio'){$('#s9repair').innerHTML=`<div class="response-box success-box">Repair successful. You diagnosed from status evidence before spending the resource.</div>${adv.next('OPEN-MISSION BOSS →')}`;adv.complete('repair',6);adv.bindNext();}else $('#s9repair').innerHTML='<div class="response-box">Which system is actually showing failure evidence?</div>';});},
 function(){stage.innerHTML=adv.header('SESSION 9 • BOSS','Data Core Exit','No labeled strategy. Just a goal, constraints, and changing information.','INDEPENDENCE BOSS')+`<div class="challenge-panel"><div class="mission-card"><span>💾</span><div><strong>Get the data core back to base.</strong><p>4 energy remain. Jungle return costs 2. Beach return costs 3. Storm arrives in 7 minutes. New clue: beach tide is rising and may block the last 100m.</p></div></div><textarea id="s9boss" class="notice-input" style="min-height:160px" placeholder="Choose your route, identify risks, and say what you would monitor while moving..."></textarea><div class="action-row"><button id="s9bossBtn" class="primary-btn">EXECUTE EXIT</button></div><div id="s9bossFeed"></div></div>`;$('#s9bossBtn').onclick=()=>{if(!adv.requireText('#s9boss'))return;adv.note('boss',$('#s9boss').value);$('#s9bossFeed').innerHTML=`<div class="response-box success-box"><b>DATA CORE RECOVERED.</b> There was no single button labeled “use flexibility” or “ask for help.” You had to decide which thinking moves were useful.</div>${adv.next('DEBRIEF →')}`;adv.complete('boss',10);adv.bindNext();};},
 function(){adv.finish('Open Mission Complete','This was the first major independence test: choosing strategies without being told which executive-functioning skill the mission was designed to practice.');}
]};

// ---------- SESSION 10: SCHOOL REPLAY LAB ----------
window.ZACH_SESSIONS[10]={title:'School Replay Lab',ef:'Regulation • Flexibility • Self-Monitoring • Help-Seeking',stages:[
 function(){stage.innerHTML=adv.header('SESSION 10','Replay Lab','Use a real school moment if you have one. If not, use the built-in second-grade scenarios.','REAL-LIFE COACHING')+`<div class="challenge-panel"><p class="instruction">Choose the source for today’s replay.</p><div class="choice-grid">${adv.choice('real','🏫','A real school moment','Something that actually happened this week.')}${adv.choice('directions','📋','Confusing directions','Teacher directions feel unclear.')}${adv.choice('hard','🧩','Work feels too hard','A new task causes resistance.')}${adv.choice('change','🔄','Plan changed','Schedule/partner/material changed.')}</div><div id="s10source"></div></div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{adv.note('source',b.dataset.choice);$('#s10source').innerHTML=`<textarea id="s10event" class="notice-input" style="min-height:140px" placeholder="Describe what happened (or make the built-in scenario more specific)..."></textarea><div class="action-row"><button id="s10eventBtn" class="primary-btn">LOAD REPLAY</button></div>`;$('#s10eventBtn').onclick=()=>{if(!adv.requireText('#s10event'))return;adv.note('event',$('#s10event').value);window.zachAdvanceSessionStep();};});},
 function(){stage.innerHTML=adv.header('REPLAY 1','Freeze the Moment','Find the first point where the situation started to feel hard—not the point where it finally blew up.','SELF-MONITORING')+`<div class="challenge-panel"><div class="replay-timeline"><button data-point="start">🙂 Start</button><button data-point="notice">🤔 First uncertainty</button><button data-point="resist">😣 Resistance</button><button data-point="adult">🗣️ Adult steps in</button><button data-point="finish">✅ Finish</button></div><textarea id="s10freeze" class="notice-input" placeholder="What was the first clue that your brain/body was getting stuck?"></textarea><div class="action-row"><button id="s10freezeBtn" class="primary-btn">MARK THE MOMENT</button></div><div id="s10freezeFeed"></div></div>`;$('#s10freezeBtn').onclick=()=>{if(!adv.requireText('#s10freeze'))return;adv.note('freeze',$('#s10freeze').value);$('#s10freezeFeed').innerHTML=`<div class="response-box success-box">The earlier you notice the moment, the more choices you still have.</div>${adv.next('WHAT DID YOUR BRAIN SAY? →')}`;adv.bindNext();};},
 function(){stage.innerHTML=adv.header('REPLAY 2','Brain Message vs. Facts','A thought can feel true without being useful or accurate.','REGULATION')+`<div class="challenge-panel"><p class="instruction">What did your brain seem to say in that moment?</p><div class="choice-grid">${adv.choice('cant','💭','I can’t do this','A shutdown message.')}${adv.choice('know','❓','I don’t know what to do','An uncertainty message.')}${adv.choice('unfair','⚡','This is unfair / I don’t want to','A resistance message.')}${adv.choice('other','📝','Something else','Name it yourself.')}</div><div id="s10brain"></div></div>`;document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>{adv.note('brainMessage',b.dataset.choice);$('#s10brain').innerHTML=`<div class="response-box blue-box"><b>Replay phrase:</b> New doesn’t mean impossible. A brain message is a signal to choose a tool, not a verdict about what you can do.</div>${adv.next('CHOOSE A NEW RESPONSE →')}`;adv.bindNext();});},
 function(){stage.innerHTML=adv.header('REPLAY 3','Run It Again','Keep the same school situation. Change your response at the critical moment.','REHEARSAL')+`<div class="challenge-panel"><div class="tool-choice-grid"><button data-toolchoice="look">👀 LOOK</button><button data-toolchoice="try">🚀 TRY ONE THING</button><button data-toolchoice="turtle">🐢 RESET</button><button data-toolchoice="ask">🙋 ASK SPECIFICALLY</button><button data-toolchoice="check">🔍 CHECK</button></div><textarea id="s10rerun" class="notice-input" placeholder="What would the new version look/sound like?"></textarea><div class="action-row"><button id="s10rerunBtn" class="primary-btn">RUN NEW VERSION</button></div><div id="s10rerunFeed"></div></div>`;$('#s10rerunBtn').onclick=()=>{if(!adv.requireText('#s10rerun'))return;adv.note('rerun',$('#s10rerun').value);$('#s10rerunFeed').innerHTML=`<div class="response-box success-box">That is transfer: taking a strategy that works here and rehearsing it for the place where you actually need it.</div>${adv.next('SCHOOL SIMULATION →')}`;adv.complete('replay',8);adv.bindNext();};},
 function(){stage.innerHTML=adv.header('LIVE REPLAY','Teacher Hands You Something New','Practice the new response immediately.','SECOND GRADE SIM')+`<div class="challenge-panel"><div class="reading-card">“Zach, complete the pattern table, explain the rule in one sentence, and then compare your rule with your partner’s.” No example is shown.</div><p class="instruction">What do you do in the first 20 seconds?</p><textarea id="s10live" class="notice-input" placeholder="First I..."></textarea><div class="action-row"><button id="s10liveBtn" class="primary-btn">PLAY IT OUT</button></div><div id="s10liveFeed"></div></div>`;$('#s10liveBtn').onclick=()=>{if(!adv.requireText('#s10live'))return;adv.note('live',$('#s10live').value);$('#s10liveFeed').innerHTML=`<div class="response-box blue-box">A strong replay usually starts with LOOK → identify the first doable part → TRY → CHECK. If a direction itself is missing, ASK specifically.</div>${adv.next('TRANSFER DEBRIEF →')}`;adv.complete('live',6);adv.bindNext();};},
 function(){adv.finish('School Replay Complete','Tutoring performance matters less here than recognizing executive-functioning moments in actual school and rehearsing a better response before the next one happens.');}
]};

// ---------- SESSION 11: REAL-WORLD TRANSFER ----------
window.ZACH_SESSIONS[11]={title:'Real-World Transfer Mission',ef:'Initiation • Persistence • Flexibility • Regulation • Focus',stages:[
 function(){stage.innerHTML=adv.header('SESSION 11','Real-World Mode','Less game scaffolding. More ordinary tasks that still require the same brain moves.','TRANSFER')+`<div class="challenge-panel ordinary-task"><h4>Task 1 — Teacher Directions</h4><p>Read a short paragraph, underline two details that support the main idea, answer one question, and check your work.</p><textarea id="s11start" class="notice-input" placeholder="Without a mission story, what is your first move?"></textarea><div class="action-row"><button id="s11startBtn" class="primary-btn">BEGIN</button></div><div id="s11startFeed"></div></div>`;$('#s11startBtn').onclick=()=>{if(!adv.requireText('#s11start'))return;adv.note('ordinaryStart',$('#s11start').value);$('#s11startFeed').innerHTML=`<div class="response-box success-box">Same brain skill, less decoration: you initiated without waiting for someone to break the task into pieces.</div>${adv.next('READING TASK →')}`;adv.bindNext();};},
 function(){stage.innerHTML=adv.header('TRANSFER 1','Ordinary Reading','Use school-like material with minimal scaffolding.','READING CONFIDENCE')+`<div class="reading-card">Beavers change their environment by building dams from branches, mud, and stones. The dam slows moving water and can create a pond. That pond gives beavers safer access to food and shelter, while also creating habitat for frogs, insects, fish, and birds.</div><div class="challenge-panel"><p class="instruction">Main idea: What important change do beavers cause, and give two details that support it.</p><textarea id="s11read" class="notice-input"></textarea><div class="action-row"><button id="s11readBtn" class="primary-btn">CHECK EVIDENCE</button></div><div id="s11readFeed"></div></div>`;$('#s11readBtn').onclick=()=>{if(!adv.requireText('#s11read'))return;adv.note('reading',$('#s11read').value);$('#s11readFeed').innerHTML=`<div class="response-box blue-box">Look for a claim plus evidence: dams slow water/create ponds; ponds improve beaver access and create habitat for other animals.</div>${adv.next('EVERYDAY PLAN →')}`;adv.complete('reading',6);adv.bindNext();};},
 function(){stage.innerHTML=adv.header('TRANSFER 2','After-School Plan','Everyday planning uses the same executive functions as mission planning.','REAL LIFE')+`<div class="challenge-panel ordinary-task"><p>You arrive home at 4:00. You need 20 minutes of reading, pack your school bag, feed the dog before 5:00, and leave for martial arts at 5:30. You also want 25 minutes of game time.</p><textarea id="s11plan" class="notice-input" style="min-height:150px" placeholder="Build a workable order and explain one reason for it..."></textarea><div class="action-row"><button id="s11planBtn" class="primary-btn">TEST SCHEDULE</button></div><div id="s11planFeed"></div></div>`;$('#s11planBtn').onclick=()=>{if(!adv.requireText('#s11plan'))return;adv.note('realPlan',$('#s11plan').value);$('#s11planFeed').innerHTML=`<div class="response-box success-box">The important constraint is feeding the dog before 5:00 and protecting the 5:30 departure. There can be more than one good sequence.</div>${adv.next('NEW SKILL PRACTICE →')}`;adv.complete('plan',6);adv.bindNext();};},
 function(){let tries=0;stage.innerHTML=adv.header('TRANSFER 3','Practice Something New','New skills often feel awkward before they feel easy.','PRODUCTIVE STRUGGLE')+`<div class="challenge-panel ordinary-task"><p class="instruction">Memory sequence: ✋ → 👊 → ✌️ → 👍 → 👊. Study it, hide it, then reproduce it in order.</p><div id="s11seq" class="code-display"><span class="code-chip">✋</span><span class="code-chip">👊</span><span class="code-chip">✌️</span><span class="code-chip">👍</span><span class="code-chip">👊</span></div><div class="action-row"><button id="s11hide" class="primary-btn">HIDE SEQUENCE</button></div><div id="s11memory"></div></div>`;$('#s11hide').onclick=()=>{$('#s11seq').innerHTML='';$('#s11memory').innerHTML=`<input id="s11memoryInput" class="notice-input" placeholder="Type the five symbols or describe them in order"><div class="action-row"><button id="s11memoryBtn" class="primary-btn">CHECK</button></div><div id="s11memoryFeed"></div>`;$('#s11memoryBtn').onclick=()=>{tries++;const v=$('#s11memoryInput').value;if(v.includes('✋')&&v.includes('✌️')&&v.includes('👍')){$('#s11memoryFeed').innerHTML=`<div class="response-box success-box">You practiced, checked, and tried again if needed. That pattern transfers to academics, sports, music, and martial arts.</div>${adv.next('MINIMAL-SCAFFOLD BOSS →')}`;adv.note('memoryTries',tries);adv.complete('practice',6);adv.bindNext();}else $('#s11memoryFeed').innerHTML='<div class="response-box">Not yet. Decide what memory strategy you want to use before another attempt.</div>';};};},
 function(){stage.innerHTML=adv.header('SESSION 11 • BOSS','Independent Work Sample','This looks more like school than a game. Use the same tools anyway.','TRANSFER BOSS')+`<div class="challenge-panel ordinary-task"><h4>Independent Work</h4><p>1. Read: “A seed needs water, air, and the right temperature to begin growing.”<br>2. Explain why a seed kept dry might not sprout.<br>3. Write one question you still have about seeds.<br>4. Check that your answer uses evidence from the sentence.</p><textarea id="s11boss" class="notice-input" style="min-height:180px"></textarea><div class="action-row"><button id="s11bossBtn" class="primary-btn">TURN IN</button></div><div id="s11bossFeed"></div></div>`;$('#s11bossBtn').onclick=()=>{if(!adv.requireText('#s11boss'))return;adv.note('boss',$('#s11boss').value);$('#s11bossFeed').innerHTML=`<div class="response-box success-box"><b>Transfer evidence:</b> You handled a normal-looking academic task without needing the Challenge Lab story to tell you how to start.</div>${adv.next('DEBRIEF →')}`;adv.complete('boss',10);adv.bindNext();};},
 function(){adv.finish('Real-World Transfer Complete','The test is whether Zach can access the same strategies when the task looks ordinary, school-like, or everyday rather than like a game mission.');}
]};

// ---------- SESSION 12: INDEPENDENCE CHECKPOINT ----------
window.ZACH_SESSIONS[12]={title:'Independence Checkpoint + Next Arc',ef:'All EF skills • repeated measures • transfer',stages:[
 function(){stage.innerHTML=adv.header('SESSION 12','Checkpoint: Unknown Start','This looks new on purpose. Start without waiting for the rules to become comfortable.','REPEATED MEASURE')+`<div class="challenge-panel"><div class="pattern-board"><div class="pattern-tile">◆<br>4</div><div class="pattern-tile">●<br>8</div><div class="pattern-tile">▲<br>16</div><div class="pattern-tile unknown">?</div></div><textarea id="s12unknown" class="notice-input" placeholder="What do you notice? What would you test first?"></textarea><div class="action-row"><button id="s12unknownBtn" class="primary-btn">TEST IDEA</button></div><div id="s12unknownFeed"></div></div>`;$('#s12unknownBtn').onclick=()=>{if(!adv.requireText('#s12unknown'))return;adv.note('unknown',$('#s12unknown').value);$('#s12unknownFeed').innerHTML=`<div class="response-box blue-box">Checkpoint recorded. The key measure is how independently you entered the uncertainty.</div>${adv.next('PERSISTENCE CHECK →')}`;adv.bindNext();};},
 function(){let attempt=0;stage.innerHTML=adv.header('CHECKPOINT 2','First Try Fails','Observe what happens after failure.','PERSISTENCE + REGULATION')+`<div class="challenge-panel"><div class="launch-strip"><span>🎯 Target 50</span><span>Controls: +7, +9, ×2</span><span>Start: 5</span></div><textarea id="s12math" class="notice-input" placeholder="Build a sequence of operations to reach exactly 50..."></textarea><div class="action-row"><button id="s12mathBtn" class="primary-btn">TEST</button></div><div id="s12mathFeed"></div></div>`;$('#s12mathBtn').onclick=()=>{attempt++;if(attempt===1){$('#s12mathFeed').innerHTML='<div class="response-box alert-box"><b>TEST FAILED.</b> Your first sequence does not reach 50. What did the attempt teach you? Revise it.</div>';return;}adv.note('persistenceAttempts',attempt);$('#s12mathFeed').innerHTML=`<div class="response-box success-box">Checkpoint saved: recovery and retry behavior matter more here than whether the arithmetic path was immediate.</div>${adv.next('FLEXIBILITY CHECK →')}`;adv.bindNext();};},
 function(){stage.innerHTML=adv.header('CHECKPOINT 3','Rule Change','Measure whether Zach notices exactly what the change affects.','FLEXIBILITY')+`<div class="challenge-panel"><div class="plan-board"><b>Original:</b> Deliver 3 packages using Route A. Route A costs 4 energy. You have 7.</div><div class="incoming-alert"><div class="alert-pulse">⚠️</div><div><strong>NEW RULE: Route A now costs 8. Route B costs 6.</strong></div></div><p class="instruction">What changes and what stays?</p><textarea id="s12flex" class="notice-input"></textarea><div class="action-row"><button id="s12flexBtn" class="primary-btn">COMMIT</button></div><div id="s12flexFeed"></div></div>`;$('#s12flexBtn').onclick=()=>{if(!adv.requireText('#s12flex'))return;adv.note('flex',$('#s12flex').value);$('#s12flexFeed').innerHTML=`<div class="response-box success-box">Goal stays: 3 packages. Route changes because A no longer fits the energy constraint.</div>${adv.next('HELP-SEEKING CHECK →')}`;adv.bindNext();};},
 function(){stage.innerHTML=adv.header('CHECKPOINT 4','Missing Information','Measure whether Zach recognizes when independent work requires a specific question.','HELP-SEEKING')+`<div class="challenge-panel"><div class="reading-card">“Sort the six cards using the two categories from yesterday.”</div><div class="response-box alert-box">The category names are not shown anywhere on the screen.</div><textarea id="s12help" class="notice-input" placeholder="What would you do or ask?"></textarea><div class="action-row"><button id="s12helpBtn" class="primary-btn">RESPOND</button></div><div id="s12helpFeed"></div></div>`;$('#s12helpBtn').onclick=()=>{if(!adv.requireText('#s12help'))return;adv.note('help',$('#s12help').value);$('#s12helpFeed').innerHTML=`<div class="response-box blue-box">Checkpoint saved. The strongest response names the exact missing information rather than saying only “I don’t know.”</div>${adv.next('SELF-MONITOR CHECK →')}`;adv.bindNext();};},
 function(){stage.innerHTML=adv.header('CHECKPOINT 5','Catch Your Own Error','No one tells you where the mistake is.','SELF-MONITORING')+`<div class="challenge-panel"><div class="error-card">Work sample:<br>12 + 9 = 21<br>21 − 4 = 18<br>18 + 2 = 20</div><textarea id="s12monitor" class="notice-input" placeholder="Check the work. Is anything wrong? Prove it."></textarea><div class="action-row"><button id="s12monitorBtn" class="primary-btn">CHECK</button></div><div id="s12monitorFeed"></div></div>`;$('#s12monitorBtn').onclick=()=>{if(!adv.requireText('#s12monitor'))return;adv.note('monitor',$('#s12monitor').value);$('#s12monitorFeed').innerHTML=`<div class="response-box success-box">The error is 21 − 4 = 17, not 18. What matters is whether Zach searched and verified without being pointed to the exact line.</div>${adv.next('FINAL INDEPENDENCE MISSION →')}`;adv.bindNext();};},
 function(){stage.innerHTML=adv.header('FINAL CHECKPOINT','Independent Mission','Several demands are mixed together. No strategy is announced.','FINAL MEASURE')+`<div class="challenge-panel"><div class="mission-card"><span>🛰️</span><div><strong>Restore the classroom weather station.</strong><p>Battery works. Display works. Sensor sends no data. A replacement sensor is in Cabinet B, but the cabinet label sheet is partly torn. You have 8 minutes, a screwdriver, and one chance to ask the teacher a question before she starts a meeting.</p></div></div><textarea id="s12final" class="notice-input" style="min-height:200px" placeholder="Talk through or write your plan. What do you do first? What would make you change plans? When would you ask?"></textarea><div class="action-row"><button id="s12finalBtn" class="primary-btn">RUN FINAL MISSION</button></div><div id="s12finalFeed"></div></div>`;$('#s12finalBtn').onclick=()=>{if(!adv.requireText('#s12final'))return;adv.note('finalMission',$('#s12final').value);$('#s12finalFeed').innerHTML=`<div class="response-box success-box"><b>CHECKPOINT COMPLETE.</b> Use the tutor rubric to compare initiation, persistence, flexibility, regulation, focus, help-seeking, self-monitoring, latency, recovery, prompts, and negative self-talk with the Session 1 baseline.</div>${adv.next('NEXT-ARC DECISION →')}`;adv.complete('final',12);adv.bindNext();};},
 function(){stage.innerHTML=adv.header('NEXT ARC','What Comes Next?','The next program should be chosen from evidence, not from a preset calendar.','TUTOR DECISION')+`<div class="challenge-panel"><div class="next-arc-grid"><div><b>Continue independence/transfer</b><small>If skills are improving across settings.</small></div><div><b>Concentrate on one lagging EF skill</b><small>If one score remains clearly lower.</small></div><div><b>Increase reading challenge</b><small>If EF improves but reading uncertainty still triggers resistance.</small></div><div><b>Increase classroom simulation</b><small>If tutoring performance exceeds school transfer.</small></div><div><b>Fade scaffolds further</b><small>If Zach is independently selecting tools.</small></div></div><div class="response-box blue-box"><b>Family deliverable:</b> Compare trend data with the Session 1 baseline and summarize changes using specific examples.</div></div>`;},
]};
